	public GeoRegion updateGeoRegion( UpdateGeoRegionCommand command ) {

		GeoRegion entity = new GeoRegion();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setGeoRegionId( command.getGeoRegionId() );
            entity.setCode( command.getCode() );
            entity.setName( command.getName() );
            entity.setParent( command.getParent() );
            entity.setChildren( command.getChildren() );
            entity.setRegionType( command.getRegionType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of GeoRegion {0} ", entity.toString() );

		return entity;
	}

